export const SOURCES: Record<string, string> = {
  "server.ts": "/**\n * Copilot Runtime for this harness.\n *\n * Verbatim in shape from the Angular quickstart's Node runtime server\n * (https://docs.copilotkit.ai/angular), which registers CopilotKit's own\n * `BuiltInAgent` as the `default` agent. There is no separate agent process:\n * `BuiltInAgent` calls the model provider directly from this file, so the whole\n * stack is two processes — this runtime and `ng serve`.\n *\n * `default` and `support` are two instances of the same agent. `support` exists\n * so the doc snippets that use `agentId=\"support\"` (Chat UI, Threads) run\n * verbatim.\n *\n * `a2ui: {}` enables A2UIMiddleware for every registered agent, per\n * https://docs.copilotkit.ai/angular/guides/a2ui\n */\nimport { createServer } from 'node:http';\nimport {\n  BuiltInAgent,\n  CopilotKitIntelligence,\n  CopilotRuntime,\n  defineTool,\n} from '@copilotkit/runtime/v2';\nimport { createCopilotNodeListener } from '@copilotkit/runtime/v2/node';\nimport { z } from 'zod';\n\nimport * as advancedConfiguration from './agents/advanced-configuration';\nimport * as mcpServers from './agents/mcp-servers';\nimport * as modelSelection from './agents/model-selection';\nimport * as serverTools from './agents/server-tools';\n\n// The quickstart's model string. `BuiltInAgent` resolves \"provider:model\" (or\n// \"provider/model\") against @ai-sdk, and reads the matching provider key from\n// the environment — OPENAI_API_KEY here, ANTHROPIC_API_KEY or GOOGLE_API_KEY if\n// you point MODEL at one of those providers instead.\nconst model = process.env['COPILOTKIT_MODEL'] ?? 'openai:gpt-5-mini';\n\nconst prompt = 'You are a helpful assistant for an Angular app.';\n\n/**\n * The one server-side tool this harness needs.\n *\n * https://docs.copilotkit.ai/angular/guides/frontend-tools-generative-ui splits\n * tools in two: `registerFrontendTool` runs in the browser and needs nothing\n * here, but `registerRenderToolCall` only *renders* a tool the agent owns — so\n * `getWeather` has to exist on this side or the guide's renderer never fires.\n *\n * The name and the `city` argument are fixed by the guide's snippet:\n * `registerRenderToolCall({ name: 'getWeather', args: z.object({ city }) })`\n * matches by exact string, and a mismatch fails silently — the agent answers in\n * plain text where the card should be.\n *\n * The reading is invented. Nothing here calls a weather service; the point is\n * the render path, not the data.\n */\nconst getWeather = defineTool({\n  name: 'getWeather',\n  description: 'Get the current weather for a city',\n  parameters: z.object({ city: z.string() }),\n  execute: async ({ city }) => ({\n    city,\n    temperature: 22,\n    conditions: 'Partly cloudy',\n    humidity: 58,\n    windSpeed: 12,\n  }),\n});\n\n/**\n * `maxSteps` is the one option this harness adds to the quickstart's model and\n * prompt. It defaults to 1, which ends the run as soon as the model emits a\n * tool call — the frontend-tools, human-in-the-loop, and shared-state routes\n * all need the model to keep going once the tool result comes back, so they\n * need more than one step to finish a turn.\n */\nconst agent = () => new BuiltInAgent({ model, prompt, maxSteps: 10, tools: [getWeather] });\n\n// Create the Intelligence client with your project API key. Keep this key on the server.\nconst intelligence = new CopilotKitIntelligence({\n  apiKey: process.env.CPK_INTELLIGENCE_API_KEY!,\n});\n\n/**\n * The Intelligence quickstart calls `authenticateApplicationUser` but leaves it\n * to the app. This harness has no login, so it uses the fixed identity the doc\n * allows \"only for a local, single-user demo\".\n */\nasync function authenticateApplicationUser(_request: Request) {\n  return { id: 'local-user', name: 'Local User' };\n}\n\nconst runtime = new CopilotRuntime({\n  agents: {\n    default: agent(),\n    support: agent(),\n  },\n  a2ui: {},\n  // Pass the Intelligence client to the runtime\n  intelligence,\n  // Identify the user from a verified session or token\n  identifyUser: async (request) => {\n    const user = await authenticateApplicationUser(request);\n    if (!user) throw new Error(\"Unauthorized\");\n    return { id: user.id, name: user.name };\n  },\n});\n\n// built-in-agent pages : separate runtime start\n/**\n * The Built-in Agent pages (Server Tools, MCP Servers, Model Selection,\n * Advanced Configuration) each show `new BuiltInAgent({...})` and nothing\n * about registering it. Every runnable snippet is registered under its own key\n * so each route's demo can bind a chat to exactly that configuration. The\n * snippets live verbatim in `agents/`.\n *\n * They are served by a second runtime, without Intelligence, at\n * `/api/copilotkit-builtin`. Registered on the Intelligence runtime above, the\n * nineteen extra agents broke chat on every route: the browser timed out\n * joining the run's realtime channel. With only `default` and `support` it\n * does not. The four demo routes point their own `provideCopilotKit` here.\n */\nconst builtInAgentPages = {\n  'server-tools': serverTools.definingATool(),\n  'mcp-sse': mcpServers.sseTransport(),\n  'mcp-sse-auth': mcpServers.authenticationHeaders(),\n  'mcp-http': mcpServers.httpTransport(),\n  'mcp-multiple': mcpServers.multipleServers(),\n  'mcp-collisions': mcpServers.toolNameCollisions(),\n  'mcp-with-server-tools': mcpServers.combiningWithServerTools(),\n  'model-openai': modelSelection.openAi(),\n  'model-anthropic': modelSelection.anthropic(),\n  'model-google': modelSelection.google(),\n  'model-api-key': modelSelection.apiKeyInConfiguration(),\n  'adv-tool-choice': advancedConfiguration.toolChoice(),\n  'adv-system-prompt': advancedConfiguration.systemPrompt(),\n  'adv-generation': advancedConfiguration.generationParameters(),\n  'adv-openai-reasoning': advancedConfiguration.openAiReasoningEffort(),\n  'adv-anthropic-thinking': advancedConfiguration.anthropicAdaptiveThinking(),\n  'adv-overridable': advancedConfiguration.overridableProperties(),\n  'adv-message-forwarding': advancedConfiguration.messageForwarding(),\n};\n\n/**\n * \"User-managed MCP clients\" connects to the MCP server before the agent\n * exists. If `../mcp-server` is not up yet, only this key is missing — the\n * rest of the runtime keeps serving — and the next request tries again.\n */\nlet mcpClientsAgent: Promise<BuiltInAgent> | undefined;\nasync function resolveMcpClientsAgent(): Promise<BuiltInAgent | undefined> {\n  mcpClientsAgent ??= mcpServers.userManagedMcpClients();\n  try {\n    return await mcpClientsAgent;\n  } catch (error) {\n    mcpClientsAgent = undefined;\n    console.error('[mcp-clients] could not connect to the MCP server:', error);\n    return undefined;\n  }\n}\n\nconst builtInAgentRuntime = new CopilotRuntime({\n  agents: async () => {\n    const mcpClients = await resolveMcpClientsAgent();\n    return {\n      ...builtInAgentPages,\n      ...(mcpClients ? { 'mcp-clients': mcpClients } : {}),\n    };\n  },\n});\n\nconst builtInAgentListener = createCopilotNodeListener({\n  runtime: builtInAgentRuntime,\n  basePath: '/api/copilotkit-builtin',\n  cors: true,\n});\n// built-in-agent pages : separate runtime end\n\nconst port = Number(process.env['PORT'] ?? 8200);\n\nconst listener = createCopilotNodeListener({\n  runtime,\n  basePath: '/api/copilotkit',\n  cors: true,\n});\n\ncreateServer((req, res) =>\n  req.url?.startsWith('/api/copilotkit-builtin')\n    ? builtInAgentListener(req, res)\n    : listener(req, res),\n).listen(port, () => {\n  console.log(`Copilot Runtime listening at http://localhost:${port}/api/copilotkit`);\n  console.log(`Built-in Agent pages runtime at http://localhost:${port}/api/copilotkit-builtin`);\n  console.log(`Built-in agent model: ${model}`);\n  if (!process.env['OPENAI_API_KEY'] && model.startsWith('openai')) {\n    console.warn('OPENAI_API_KEY is not set — the agent will fail on the first message.');\n  }\n});\n",
  "agents/advanced-configuration.ts": "/**\n * Advanced Configuration — the page's runnable snippets.\n * https://docs.copilotkit.ai/angular/advanced-configuration\n *\n * Each snippet's body is verbatim inside a function, so `server.ts` can\n * register it under its own key; the page shows no runtime registration.\n *\n * Not wired:\n * - \"Multi-step tool calling\": `searchDocs` and `createTicket` are not\n *   defined on this page (they come from Server Tools, where they depend on\n *   the undefined `search` and `db`).\n *\n * \"Overridable properties\" is wired, but the page shows only the agent side —\n * no frontend code that sends an override — so the chat bound to it behaves\n * like any other. See the route page and README Known issues.\n */\nimport { BuiltInAgent } from \"@copilotkit/runtime/v2\";\n\n// advanced-configuration : \"Tool choice\" start\nexport function toolChoice() {\n  const agent = new BuiltInAgent({\n    model: \"openai:gpt-5.4-mini\",\n    toolChoice: \"auto\",       // Let the model decide (default)\n    // toolChoice: \"required\", // Force the model to call a tool\n    // toolChoice: \"none\",     // Disable tool calling\n    // toolChoice: { type: \"tool\", toolName: \"searchDocs\" }, // Force a specific tool\n  });\n\n  return agent;\n}\n// advanced-configuration : \"Tool choice\" end\n\n// advanced-configuration : \"System prompt\" start\nexport function systemPrompt() {\n  const agent = new BuiltInAgent({\n    model: \"openai:gpt-5.4-mini\",\n    prompt: \"You are a customer support agent for Acme Corp. Be concise and helpful. Always check the knowledge base before answering.\", // [!code highlight]\n  });\n\n  return agent;\n}\n// advanced-configuration : \"System prompt\" end\n\n// advanced-configuration : \"Generation parameters\" start\nexport function generationParameters() {\n  const agent = new BuiltInAgent({\n    model: \"openai:gpt-5.4-mini\",\n    temperature: 0.7,        // Creativity (0 = deterministic, 1+ = creative)\n    topP: 0.9,               // Nucleus sampling\n    topK: 40,                // Top-K sampling (provider-dependent)\n    maxOutputTokens: 4096,   // Maximum tokens in the response\n    presencePenalty: 0.1,    // Penalize repeated topics\n    frequencyPenalty: 0.1,   // Penalize repeated tokens\n    stopSequences: [\"END\"],  // Stop generation at these sequences\n    seed: 42,                // Deterministic output (provider-dependent)\n    maxRetries: 3,           // Retry on transient failures\n  });\n\n  return agent;\n}\n// advanced-configuration : \"Generation parameters\" end\n\n// advanced-configuration : \"Provider-specific options\" — OpenAI start\nexport function openAiReasoningEffort() {\n  // OpenAI reasoning models (o3, o4-mini) with reasoning effort\n  const agent = new BuiltInAgent({\n    model: \"openai:o3\",\n    providerOptions: { // [!code highlight:3]\n      openai: { reasoningEffort: \"high\" },\n    },\n  });\n\n  return agent;\n}\n// advanced-configuration : \"Provider-specific options\" — OpenAI end\n\n// advanced-configuration : \"Provider-specific options\" — Anthropic start\nexport function anthropicAdaptiveThinking() {\n  // Anthropic with adaptive thinking\n  const agent = new BuiltInAgent({\n    model: \"anthropic:claude-sonnet-4-6\",\n    providerOptions: { // [!code highlight:3]\n      anthropic: { thinking: { type: \"adaptive\" }, effort: \"high\" },\n    },\n  });\n\n  return agent;\n}\n// advanced-configuration : \"Provider-specific options\" — Anthropic end\n\n// advanced-configuration : \"Overridable properties\" start\nexport function overridableProperties() {\n  const agent = new BuiltInAgent({\n    model: \"openai:gpt-5.4-mini\",\n    temperature: 0.5,\n    overridableProperties: [\"model\", \"temperature\", \"prompt\"], // [!code highlight]\n  });\n\n  return agent;\n}\n// advanced-configuration : \"Overridable properties\" end\n\n// advanced-configuration : \"Message forwarding\" start\nexport function messageForwarding() {\n  const agent = new BuiltInAgent({\n    model: \"openai:gpt-5.4-mini\",\n    forwardSystemMessages: true,    // Forward system-role messages\n    forwardDeveloperMessages: true, // Forward developer-role messages (as system messages)\n  });\n\n  return agent;\n}\n// advanced-configuration : \"Message forwarding\" end\n",
  "agents/mcp-servers.ts": "/**\n * MCP Servers — the page's runnable snippets.\n * https://docs.copilotkit.ai/angular/mcp-servers\n *\n * Each snippet's body is verbatim inside a function, so `server.ts` can\n * register it under its own key; the page shows no runtime registration.\n *\n * ADDED to every snippet: `maxSteps: 2`. None of the page's snippets set it,\n * so it stays at the default of 1 and the run ends at the MCP tool call with\n * no answer. 2 is the value the Server Tools page uses, with the comment\n * \"Important for tool calls\".\n *\n * The one change to every snippet is the URL. The page points at placeholder\n * hosts (`https://my-mcp-server.example.com/sse`, …); here each one is the\n * same path on the harness's own MCP server (`../mcp-server`), with the\n * placeholder's subdomain as the first path segment, so the mapping stays\n * readable: `https://search-mcp.example.com/sse` → `${MCP}/search-mcp/sse`.\n *\n * Not wired, because the snippets use identifiers the page never defines —\n * see the route page and README Known issues:\n * - \"Tool caching\": `ToolSet`, `transport` (from the previous snippet)\n * - \"Dynamic authentication\": `isTokenExpired`, `currentClient`,\n *   `makeTransport`, `getFreshToken`\n * - \"Combining with mcpServers\": `persistentClient`\n */\nimport { BuiltInAgent, defineTool } from \"@copilotkit/runtime/v2\";\nimport { createMCPClient } from \"@ai-sdk/mcp\";\nimport { StreamableHTTPClientTransport } from \"@modelcontextprotocol/sdk/client/streamableHttp.js\";\nimport { z } from \"zod\";\n\n/** Base URL of `../mcp-server`. Replaces the page's placeholder hosts. */\nconst MCP = process.env[\"MCP_SERVER_URL\"] ?? \"http://localhost:8300\";\n\n// mcp-servers : \"SSE transport\" start\nexport function sseTransport() {\n  const builtInAgent = new BuiltInAgent({\n    model: \"openai:gpt-5.4-mini\",\n    maxSteps: 2, // ADDED — not in the MCP page; see the header comment\n    mcpServers: [\n      {\n        type: \"sse\", // [!code highlight]\n        url: `${MCP}/my-mcp-server/sse`,\n      },\n    ],\n  });\n\n  return builtInAgent;\n}\n// mcp-servers : \"SSE transport\" end\n\n// mcp-servers : \"Authentication headers\" start\nexport function authenticationHeaders() {\n  const builtInAgent = new BuiltInAgent({\n    model: \"openai:gpt-5.4-mini\",\n    maxSteps: 2, // ADDED — not in the MCP page; see the header comment\n    mcpServers: [\n      {\n        type: \"sse\",\n        url: `${MCP}/my-mcp-server/sse`,\n        headers: { // [!code highlight:3]\n          Authorization: `Bearer ${process.env.MCP_API_KEY}`,\n        },\n      },\n    ],\n  });\n\n  return builtInAgent;\n}\n// mcp-servers : \"Authentication headers\" end\n\n// mcp-servers : \"HTTP transport\" start\nexport function httpTransport() {\n  const builtInAgent = new BuiltInAgent({\n    model: \"openai:gpt-5.4-mini\",\n    maxSteps: 2, // ADDED — not in the MCP page; see the header comment\n    mcpServers: [\n      {\n        type: \"http\", // [!code highlight]\n        url: `${MCP}/my-mcp-server/mcp`,\n      },\n    ],\n  });\n\n  return builtInAgent;\n}\n// mcp-servers : \"HTTP transport\" end\n\n// mcp-servers : \"Multiple servers\" start\nexport function multipleServers() {\n  const builtInAgent = new BuiltInAgent({\n    model: \"openai:gpt-5.4-mini\",\n    maxSteps: 2, // ADDED — not in the MCP page; see the header comment\n    mcpServers: [\n      {\n        type: \"sse\",\n        url: `${MCP}/search-mcp/sse`,\n      },\n      {\n        type: \"sse\",\n        url: `${MCP}/db-mcp/sse`,\n        headers: { Authorization: `Bearer ${process.env.DB_MCP_KEY}` },\n      },\n      {\n        type: \"http\",\n        url: `${MCP}/analytics-mcp/mcp`,\n      },\n    ],\n  });\n\n  return builtInAgent;\n}\n// mcp-servers : \"Multiple servers\" end\n\n// mcp-servers : \"Tool name collisions\" start\nexport function toolNameCollisions() {\n  const builtInAgent = new BuiltInAgent({\n    model: \"openai:gpt-5.4-mini\",\n    maxSteps: 2, // ADDED — not in the MCP page; see the header comment\n    mcpServers: [\n      { type: \"http\", url: `${MCP}/staging/mcp`, name: \"staging\" }, // [!code highlight]\n      { type: \"http\", url: `${MCP}/prod/mcp`, name: \"production\" }, // [!code highlight]\n    ],\n  });\n  // Both servers expose `search`, so the model sees `staging_search` and `production_search`.\n\n  return builtInAgent;\n}\n// mcp-servers : \"Tool name collisions\" end\n\n// mcp-servers : \"Combining with server tools\" start\nexport function combiningWithServerTools() {\n  const customTool = defineTool({\n    name: \"getUser\",\n    description: \"Get the current user\",\n    parameters: z.object({}),\n    execute: async () => {\n      return { name: \"Jane\", role: \"Admin\" };\n    },\n  });\n\n  const builtInAgent = new BuiltInAgent({\n    model: \"openai:gpt-5.4-mini\",\n    maxSteps: 2, // ADDED — not in the MCP page; see the header comment\n    tools: [customTool], // Your custom tools\n    mcpServers: [        // Plus tools from MCP servers\n      { type: \"sse\", url: `${MCP}/search-mcp/sse` },\n    ],\n  });\n\n  return builtInAgent;\n}\n// mcp-servers : \"Combining with server tools\" end\n\n/**\n * The page creates this client with a top-level `await`. This runtime is\n * loaded as CommonJS, where top-level `await` is a syntax error, so the\n * snippet runs inside an async function instead; `server.ts` awaits it.\n */\n// mcp-servers : \"User-managed MCP clients\" start\nexport async function userManagedMcpClients() {\n  // Create a persistent client at startup\n  const transport = new StreamableHTTPClientTransport(\n    new URL(`${MCP}/my-mcp-server/mcp`),\n  );\n  const client = await createMCPClient({ transport });\n\n  const builtInAgent = new BuiltInAgent({\n    model: \"openai:gpt-5.4-mini\",\n    maxSteps: 2, // ADDED — not in the MCP page; see the header comment\n    mcpClients: [client], // [!code highlight]\n  });\n\n  return builtInAgent;\n}\n// mcp-servers : \"User-managed MCP clients\" end\n",
  "agents/model-selection.ts": "/**\n * Model Selection — the page's runnable snippets.\n * https://docs.copilotkit.ai/angular/model-selection\n *\n * Each snippet's body is verbatim inside a function, so `server.ts` can\n * register it under its own key; the page shows no runtime registration.\n * Each provider reads its own key from the environment: OPENAI_API_KEY,\n * ANTHROPIC_API_KEY, GOOGLE_API_KEY — and MY_OPENAI_KEY for the `apiKey`\n * snippet.\n *\n * Not wired — shown on the route page as code only:\n * - MiniMax: no MINIMAX_API_KEY for this harness.\n * - \"Custom Models (AI SDK)\": a placeholder proxy (`my-proxy.example.com`,\n *   `my-fine-tuned-model`) and an Azure resource (`my-resource`,\n *   `my-deployment`) that do not exist.\n * - \"OpenRouter, proxies, and bring-your-own LLM\": no OPENROUTER_API_KEY.\n * - \"The model is set on the agent\": `openrouter(\"...\")` is a placeholder.\n */\nimport { BuiltInAgent } from \"@copilotkit/runtime/v2\";\n\n// model-selection : \"OpenAI\" start\nexport function openAi() {\n  const agent = new BuiltInAgent({\n    model: \"openai:gpt-5.4-mini\",\n  });\n\n  return agent;\n}\n// model-selection : \"OpenAI\" end\n\n// model-selection : \"Anthropic\" start\nexport function anthropic() {\n  const agent = new BuiltInAgent({\n    model: \"anthropic:claude-sonnet-4-6\",\n  });\n\n  return agent;\n}\n// model-selection : \"Anthropic\" end\n\n// model-selection : \"Google\" start\nexport function google() {\n  const agent = new BuiltInAgent({\n    model: \"google:gemini-2.5-pro\",\n  });\n\n  return agent;\n}\n// model-selection : \"Google\" end\n\n// model-selection : \"Environment Variables\" — apiKey start\nexport function apiKeyInConfiguration() {\n  const agent = new BuiltInAgent({\n    model: \"openai:gpt-5.4-mini\",\n    apiKey: process.env.MY_OPENAI_KEY, // [!code highlight]\n  });\n\n  return agent;\n}\n// model-selection : \"Environment Variables\" — apiKey end\n",
  "agents/server-tools.ts": "/**\n * Server Tools — the page's runnable snippet.\n * https://docs.copilotkit.ai/angular/server-tools\n *\n * Only \"Defining a tool\" runs as published. Its body below is verbatim; the\n * wrapping function exists so `server.ts` can register it under its own key\n * (`server-tools`), since the page shows no runtime registration.\n *\n * Not wired, because the snippets use identifiers the page never defines —\n * see the route page and README Known issues:\n * - \"Multiple tools\": `search`, `db`\n * - \"Complex Zod schemas\": `searchFlights`\n * - \"Error handling\": `db`\n * - \"Multi-step tool calling\": `searchDocs`, `createTicket`, `getUser` from\n *   the sections above, so it inherits their gaps\n */\nimport { BuiltInAgent, defineTool } from \"@copilotkit/runtime/v2\";\nimport { z } from \"zod\";\n\n// server-tools : \"Defining a tool\" start\nexport function definingATool() {\n  const getWeather = defineTool({\n    name: \"getWeather\",\n    description: \"Get the current weather for a location\",\n    parameters: z.object({\n      location: z.string().describe(\"The location's name\"),\n    }),\n    execute: async ({ location }) => {\n      // Your implementation here\n      return { temperature: 72, condition: \"sunny\", location };\n    },\n  });\n\n  const builtInAgent = new BuiltInAgent({\n    model: \"openai:gpt-5.4-mini\",\n    tools: [getWeather],\n    maxSteps: 2                   //Important for tool calls\n  });\n\n  return builtInAgent;\n}\n// server-tools : \"Defining a tool\" end\n",
  "../mcp-server/server.ts": "/**\n * Local MCP server for the MCP Servers route.\n * https://docs.copilotkit.ai/angular/mcp-servers\n *\n * SELF-DEFINED — not from the docs. The page connects the Built-in Agent to\n * MCP servers at placeholder hosts (`my-mcp-server.example.com`,\n * `search-mcp.example.com`, `staging.example.com`, …) and never defines one.\n * This process stands in for all of them: each placeholder host becomes a path\n * prefix here, so `https://search-mcp.example.com/sse` is\n * `http://localhost:8300/search-mcp/sse`.\n *\n * Every server exposes the same single tool, `search`, returning fixed\n * results tagged with the server's name — the page defines no tool content,\n * and one shared name is what the \"Tool name collisions\" section needs.\n *\n * Transports, per server:\n * - `GET  /<server>/sse` + `POST /<server>/messages` — SSE\n * - `POST /<server>/mcp` — Streamable HTTP, stateless\n *\n * No auth is enforced. The page only shows the agent sending an\n * `Authorization` header; whether it arrives is logged, nothing more.\n */\nimport { createServer, type IncomingMessage, type ServerResponse } from 'node:http';\nimport { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';\nimport { SSEServerTransport } from '@modelcontextprotocol/sdk/server/sse.js';\nimport { StreamableHTTPServerTransport } from '@modelcontextprotocol/sdk/server/streamableHttp.js';\nimport { z } from 'zod';\n\n/** The placeholder hosts used on the doc page, by subdomain. */\nconst SERVERS = [\n  'my-mcp-server',\n  'search-mcp',\n  'db-mcp',\n  'analytics-mcp',\n  'staging',\n  'prod',\n  'other-mcp',\n] as const;\n\nfunction createMcpServer(name: string): McpServer {\n  const server = new McpServer({ name, version: '1.0.0' });\n  server.registerTool(\n    'search',\n    {\n      description: `Search the ${name} index`,\n      inputSchema: { query: z.string().describe('The search query') },\n    },\n    async ({ query }) => ({\n      content: [\n        {\n          type: 'text',\n          text: JSON.stringify({\n            server: name,\n            query,\n            results: [\n              { title: `${name}: first result for \"${query}\"` },\n              { title: `${name}: second result for \"${query}\"` },\n            ],\n          }),\n        },\n      ],\n    }),\n  );\n  return server;\n}\n\n/** Live SSE sessions, by session id, so POSTed messages reach their stream. */\nconst sseSessions = new Map<string, SSEServerTransport>();\n\nfunction logAuth(server: string, req: IncomingMessage): void {\n  const auth = req.headers['authorization'];\n  console.log(\n    `[${server}] ${req.method} ${req.url} — authorization header: ${auth ? 'present' : 'absent'}`,\n  );\n}\n\nasync function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {\n  const url = new URL(req.url ?? '/', 'http://localhost');\n  const [, server, endpoint] = url.pathname.split('/');\n\n  if (!SERVERS.includes(server as (typeof SERVERS)[number])) {\n    res.writeHead(404).end(`Unknown MCP server \"${server}\"`);\n    return;\n  }\n\n  if (endpoint === 'sse' && req.method === 'GET') {\n    logAuth(server, req);\n    const transport = new SSEServerTransport(`/${server}/messages`, res);\n    sseSessions.set(transport.sessionId, transport);\n    res.on('close', () => sseSessions.delete(transport.sessionId));\n    await createMcpServer(server).connect(transport);\n    return;\n  }\n\n  if (endpoint === 'messages' && req.method === 'POST') {\n    const transport = sseSessions.get(url.searchParams.get('sessionId') ?? '');\n    if (!transport) {\n      res.writeHead(404).end('Unknown SSE session');\n      return;\n    }\n    await transport.handlePostMessage(req, res);\n    return;\n  }\n\n  if (endpoint === 'mcp' && req.method === 'POST') {\n    logAuth(server, req);\n    const transport = new StreamableHTTPServerTransport({ sessionIdGenerator: undefined });\n    res.on('close', () => transport.close());\n    await createMcpServer(server).connect(transport);\n    await transport.handleRequest(req, res);\n    return;\n  }\n\n  res.writeHead(405).end();\n}\n\nconst port = Number(process.env['MCP_PORT'] ?? 8300);\n\ncreateServer((req, res) => {\n  handle(req, res).catch((error: unknown) => {\n    console.error(error);\n    if (!res.headersSent) res.writeHead(500).end();\n  });\n}).listen(port, () => {\n  console.log(`MCP server listening at http://localhost:${port}`);\n  for (const server of SERVERS) {\n    console.log(`  /${server}/sse  /${server}/mcp`);\n  }\n});\n",
  "src/styles.css": "@import 'tailwindcss';\n\n/* Quickstart step \"Import the styles\". Self-contained — the chat renders\n   without any other CSS.\n   https://docs.copilotkit.ai/angular */\n@import '@copilotkit/angular/styles.css';\n\n/* ------------------------------------------------------------------ */\n/* Harness chrome tokens                                              */\n/* `--line` and `--muted` are referenced by the A2UI guide's CSS below, */\n/* which does not define them itself.                                  */\n/* ------------------------------------------------------------------ */\n:root {\n  /* Surfaces */\n  --bg: #f4f6fa;\n  --surface: #ffffff;\n  --surface-sunken: #eef1f7;\n\n  /* Text — all AA or better on --surface */\n  --ink: #0d1526;\n  --ink-soft: #33415a;\n  --muted: #5c6a86;\n\n  /* Lines */\n  --line: #e0e5ee;\n  --line-strong: #c6cedd;\n\n  /* Accent */\n  --accent: #4f46e5;\n  --accent-hover: #4338ca;\n  --accent-soft: #eef0ff;\n  --accent-ink: #362fa8;\n\n  /* Code surface */\n  --code-bg: #0b1220;\n  --code-bar: #131c2f;\n  --code-ink: #dbe3f0;\n  --code-line: #24304a;\n}\n\nhtml,\nbody {\n  height: 100%;\n  margin: 0;\n  color: var(--ink);\n  background: var(--bg);\n  font-family:\n    'Inter',\n    -apple-system,\n    BlinkMacSystemFont,\n    'Segoe UI',\n    Roboto,\n    Helvetica,\n    Arial,\n    sans-serif;\n  -webkit-font-smoothing: antialiased;\n}\n\n/* Visible keyboard focus everywhere in the harness chrome (WCAG 2.4.7). */\na:focus-visible,\nbutton:focus-visible,\n[tabindex]:focus-visible {\n  outline: 2px solid var(--accent);\n  outline-offset: 2px;\n  border-radius: 0.375rem;\n}\n\n/* Inline code in prose — distinct from the dark code blocks. */\n.prose-inline-code,\np > code,\nli > code,\ntd > code {\n  padding: 0.1rem 0.35rem;\n  border: 1px solid var(--line);\n  border-radius: 0.3rem;\n  background: var(--surface-sunken);\n  color: var(--accent-ink);\n  font-size: 0.85em;\n}\n\n/* ------------------------------------------------------------------ */\n/* Code figures                                                        */\n/* ------------------------------------------------------------------ */\n.code-figure {\n  overflow: hidden;\n  border: 1px solid var(--code-line);\n  border-radius: 0.75rem;\n  background: var(--code-bg);\n  box-shadow: 0 12px 28px -22px rgb(11 18 32 / 0.65);\n}\n\n/* Quoted-from-docs samples read as secondary to the code that runs. */\n.code-figure--quoted {\n  border-style: dashed;\n  border-color: var(--line-strong);\n}\n\n.code-figure__bar {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.5rem 1rem;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0.5rem 0.85rem;\n  border-bottom: 1px solid var(--code-line);\n  background: var(--code-bar);\n}\n\n.code-figure__path {\n  color: #b9c6de;\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  font-size: 0.72rem;\n  word-break: break-all;\n}\n\n.code-figure__meta {\n  display: flex;\n  flex-shrink: 0;\n  gap: 0.5rem;\n  align-items: center;\n}\n\n.code-figure__note {\n  color: #93a3c0;\n  font-size: 0.72rem;\n}\n\n.code-figure__lang,\n.code-figure__badge {\n  padding: 0.1rem 0.45rem;\n  border-radius: 999px;\n  background: #22304d;\n  color: #a9b8d6;\n  font-size: 0.65rem;\n  font-weight: 600;\n  letter-spacing: 0.02em;\n  text-transform: uppercase;\n}\n\n.code-figure__badge {\n  background: #3b2f18;\n  color: #e6c07b;\n}\n\n.code-figure__copy {\n  padding: 0.15rem 0.55rem;\n  border: 1px solid #2f3d5c;\n  border-radius: 0.35rem;\n  background: transparent;\n  color: #b9c6de;\n  font-size: 0.7rem;\n  font-weight: 600;\n  cursor: pointer;\n  transition: background 0.15s ease;\n}\n\n.code-figure__copy:hover {\n  background: #22304d;\n  color: #e6edf9;\n}\n\n.code-figure__pre {\n  max-height: 32rem;\n  margin: 0;\n  overflow: auto;\n  padding: 1rem;\n  color: var(--code-ink);\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  font-size: 0.78rem;\n  line-height: 1.65;\n  tab-size: 2;\n}\n\n/* ------------------------------------------------------------------ */\n/* highlight.js theme — tuned for contrast on --code-bg                */\n/* ------------------------------------------------------------------ */\n.hljs-comment,\n.hljs-quote {\n  color: #8494b3;\n  font-style: italic;\n}\n\n.hljs-keyword,\n.hljs-selector-tag,\n.hljs-literal,\n.hljs-doctag {\n  color: #c4b5fd;\n}\n\n.hljs-string,\n.hljs-regexp,\n.hljs-addition {\n  color: #8ee7a5;\n}\n\n.hljs-number,\n.hljs-symbol,\n.hljs-bullet {\n  color: #fcd34d;\n}\n\n.hljs-title,\n.hljs-title.function_,\n.hljs-section {\n  color: #7dd3fc;\n}\n\n.hljs-title.class_,\n.hljs-type,\n.hljs-built_in,\n.hljs-class .hljs-title {\n  color: #fdba74;\n}\n\n.hljs-attr,\n.hljs-attribute,\n.hljs-property,\n.hljs-variable,\n.hljs-template-variable {\n  color: #f0abfc;\n}\n\n.hljs-name,\n.hljs-selector-id,\n.hljs-selector-class,\n.hljs-tag {\n  color: #fb7185;\n}\n\n.hljs-meta,\n.hljs-params,\n.hljs-punctuation {\n  color: #a5b4cd;\n}\n\n.hljs-deletion {\n  color: #fca5a5;\n}\n\n.hljs-emphasis {\n  font-style: italic;\n}\n\n.hljs-strong {\n  font-weight: 700;\n}\n\n/* ------------------------------------------------------------------ */\n/* Chat UI guide — \"Scope CSS changes\"                                 */\n/* https://docs.copilotkit.ai/angular/guides/chat-ui              */\n/* ------------------------------------------------------------------ */\n.support-chat .copilotKitUserMessage {\n  color: white;\n  background: #2563eb;\n  border-radius: 0.75rem;\n}\n\n.support-chat .copilotKitAssistantMessage {\n  padding: 0.75rem;\n  color: #172554;\n  background: #eff6ff;\n  border-radius: 0.75rem;\n}\n\n/* ------------------------------------------------------------------ */\n/* A2UI guide — \"Style rendered components\"                            */\n/* https://docs.copilotkit.ai/angular/guides/a2ui                 */\n/* ------------------------------------------------------------------ */\n.a2ui-row {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: stretch;\n  width: 100%;\n}\n\n.a2ui-row > * {\n  flex: 1 1 10rem;\n  min-width: 0;\n}\n\n.a2ui-column {\n  display: flex;\n  flex-direction: column;\n  width: 100%;\n}\n\n[data-testid='declarative-card'],\n.a2ui-chart-card,\n.a2ui-flight-card {\n  display: block;\n  padding: 1rem;\n  border: 1px solid var(--line);\n  border-radius: 0.9rem;\n  background: white;\n  box-shadow: 0 8px 22px -18px rgb(15 23 42 / 0.4);\n}\n\n.a2ui-metric {\n  display: grid;\n  min-width: 8rem;\n  gap: 0.25rem;\n}\n\n.a2ui-metric > span,\n.a2ui-metric > small {\n  color: var(--muted);\n  font-size: 0.75rem;\n}\n\n.a2ui-metric > strong {\n  font-size: 1.4rem;\n}\n\n.a2ui-status,\n.a2ui-airline {\n  display: inline-flex;\n  width: fit-content;\n  padding: 0.25rem 0.55rem;\n  border-radius: 999px;\n  background: #eef2ff;\n  font-size: 0.75rem;\n  font-weight: 700;\n}\n\n.a2ui-status-success {\n  background: #dcfce7;\n  color: #166534;\n}\n.a2ui-status-warning {\n  background: #fef3c7;\n  color: #92400e;\n}\n.a2ui-status-error {\n  background: #fee2e2;\n  color: #991b1b;\n}\n",
  "src/app/app.config.ts": "import {\n  ApplicationConfig,\n  provideBrowserGlobalErrorListeners,\n} from '@angular/core';\nimport { provideRouter, withInMemoryScrolling } from '@angular/router';\nimport { provideClientHydration } from '@angular/platform-browser';\nimport {\n  provideCopilotKit,\n  type SandboxFunction,\n} from '@copilotkit/angular';\nimport { z } from 'zod';\n\nimport { routes } from './app.routes';\n\n/**\n * Host function exposed to sandboxed Open Generative UI, verbatim from\n * https://docs.copilotkit.ai/angular/guides/frontend-tools-generative-ui\n */\nconst setDashboardFilter: SandboxFunction<{ filter: string }> = {\n  name: 'setDashboardFilter',\n  description: 'Set the active dashboard filter',\n  parameters: z.object({ filter: z.string() }),\n  handler: async ({ filter }) => {\n    sessionStorage.setItem('dashboard-filter', filter);\n    return { applied: filter };\n  },\n};\n\n\n/**\n * One provider at the application root, so a conversation started on any demo\n * route continues on every other route.\n *\n * `runtimeUrl` points at the Copilot Runtime from the quickstart — the\n * supported path, where the browser never holds a model key and never talks to\n * a model provider directly. The `BuiltInAgent` that does both lives\n * server-side in frontend/server.ts.\n *\n * `a2ui.recovery` and `openGenerativeUI.sandboxFunctions` are the A2UI and\n * generative-UI guide options. No `a2ui.catalog` is set yet — supplying one is\n * what actually registers the render_a2ui renderer, so A2UI stays inert until\n * a catalog is added. See README known issues.\n */\nexport const appConfig: ApplicationConfig = {\n  providers: [\n    provideBrowserGlobalErrorListeners(),\n    provideRouter(\n      routes,\n      withInMemoryScrolling({ scrollPositionRestoration: 'top' }),\n    ),\n    provideClientHydration(),\n    provideCopilotKit({\n      runtimeUrl: 'http://localhost:8200/api/copilotkit',\n      a2ui: {\n        recovery: { showAfterMs: 2_000, showAfterAttempts: 2 },\n      },\n      openGenerativeUI: {\n        // `sandboxFunctions` is typed `SandboxFunction[]`, i.e.\n        // `SandboxFunction<Record<string, unknown>>[]`, so the guide's\n        // `SandboxFunction<{ filter: string }>` is not assignable to it as\n        // written. Cast at the array site, the same idiom the docs use for the\n        // equivalent `component` variance problem. See README known issues.\n        sandboxFunctions: [setDashboardFilter as unknown as SandboxFunction],\n      },\n    }),\n  ],\n};\n",
  "src/app/features/a2ui/a2ui-chat.component.ts": "/**\n * A2UI needs no component-level wiring: the runtime applies A2UIMiddleware\n * (`a2ui: {}` in frontend/server.ts) and, per the guide, \"on the frontend, the\n * A2UI renderer activates automatically. No extra configuration is needed.\"\n *\n * The recovery thresholds the guide prescribes are set once in\n * src/app/app.config.ts, and its catalog CSS lives in src/styles.css.\n * https://docs.copilotkit.ai/angular/guides/a2ui\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-a2ui-chat',\n  imports: [CopilotChat],\n  template: `\n    <div style=\"height: 100%\">\n      <copilot-chat />\n    </div>\n  `,\n})\nexport class A2uiChatComponent {}\n",
  "src/app/features/attachments/media-chat.component.ts": "/**\n * \"Enable attachments\", verbatim. Without `onUpload`, files are read as base64\n * and travel inline with the message.\n * https://docs.copilotkit.ai/angular/guides/threads-memory-attachments-headless\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat, type AttachmentsConfig } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-media-chat',\n  imports: [CopilotChat],\n  template: ` <copilot-chat [attachments]=\"attachments\" /> `,\n})\nexport class MediaChatComponent {\n  protected readonly attachments: AttachmentsConfig = {\n    enabled: true,\n    accept: 'image/*,application/pdf',\n    maxSize: 10 * 1024 * 1024,\n    onUploadFailed: (error) => {\n      console.error(error.reason, error.message);\n    },\n  };\n}\n",
  "src/app/features/built-in-agent/agent-options.ts": "/**\n * The agent keys each Built-in Agent route's demo can bind to. Every `id` is a\n * key registered in `server.ts`, backed by a verbatim snippet in `agents/`.\n */\nimport type { AgentOption } from './agent-picker-chat.component';\n\nexport const SERVER_TOOLS_AGENTS: AgentOption[] = [\n  {\n    id: 'server-tools',\n    section: 'Defining a tool',\n    prompt: \"What's the weather in Paris?\",\n  },\n];\n\nexport const MCP_SERVERS_AGENTS: AgentOption[] = [\n  { id: 'mcp-sse', section: 'SSE transport', prompt: 'Search for \"angular\".' },\n  {\n    id: 'mcp-sse-auth',\n    section: 'Authentication headers',\n    prompt: 'Search for \"angular\".',\n  },\n  { id: 'mcp-http', section: 'HTTP transport', prompt: 'Search for \"angular\".' },\n  {\n    id: 'mcp-multiple',\n    section: 'Multiple servers',\n    prompt: 'List the exact names of every tool you have.',\n  },\n  {\n    id: 'mcp-collisions',\n    section: 'Tool name collisions',\n    prompt: 'List the exact names of every tool you have.',\n  },\n  {\n    id: 'mcp-with-server-tools',\n    section: 'Combining with server tools',\n    prompt: 'Who is the current user?',\n  },\n  {\n    id: 'mcp-clients',\n    section: 'User-managed MCP clients',\n    prompt: 'Search for \"angular\".',\n  },\n];\n\nexport const MODEL_SELECTION_AGENTS: AgentOption[] = [\n  { id: 'model-openai', section: 'OpenAI', prompt: 'Which model are you?' },\n  { id: 'model-anthropic', section: 'Anthropic', prompt: 'Which model are you?' },\n  { id: 'model-google', section: 'Google', prompt: 'Which model are you?' },\n  {\n    id: 'model-api-key',\n    section: 'Environment Variables — apiKey',\n    prompt: 'Say hello.',\n  },\n];\n\nexport const ADVANCED_CONFIGURATION_AGENTS: AgentOption[] = [\n  { id: 'adv-tool-choice', section: 'Tool choice', prompt: 'Say hello.' },\n  {\n    id: 'adv-system-prompt',\n    section: 'System prompt',\n    prompt: 'Who do you work for?',\n  },\n  {\n    id: 'adv-generation',\n    section: 'Generation parameters',\n    prompt: 'Write a two-line poem.',\n  },\n  {\n    id: 'adv-openai-reasoning',\n    section: 'Provider-specific options — OpenAI',\n    prompt: 'What is 17 × 23?',\n  },\n  {\n    id: 'adv-anthropic-thinking',\n    section: 'Provider-specific options — Anthropic',\n    prompt: 'What is 17 × 23?',\n  },\n  {\n    id: 'adv-overridable',\n    section: 'Overridable properties',\n    prompt: 'Say hello.',\n  },\n  {\n    id: 'adv-message-forwarding',\n    section: 'Message forwarding',\n    prompt: 'Say hello.',\n  },\n];\n",
  "src/app/features/built-in-agent/agent-picker-chat.component.ts": "/**\n * Harness wrapper for the Built-in Agent pages (Server Tools, MCP Servers,\n * Model Selection, Advanced Configuration).\n *\n * SELF-DEFINED — not from the docs. Those pages show only backend\n * `new BuiltInAgent({...})` snippets and no frontend code. `server.ts`\n * registers each runnable snippet under its own key; this component is a plain\n * `copilot-chat` bound to whichever key is picked, so each configuration can\n * be exercised on its own. The `@for` over a one-item list re-creates the chat\n * when the key changes, so each agent starts from its own conversation.\n *\n * These agents live on a separate runtime in `server.ts`\n * (`/api/copilotkit-builtin`, no Intelligence). `CopilotKit` is a root\n * singleton, so a component-level `provideCopilotKit` is never read; instead\n * this component points the root instance at that runtime with the public\n * `updateRuntime`, and restores the previous URL when it is destroyed.\n */\nimport { Component, DestroyRef, inject, input, linkedSignal } from '@angular/core';\nimport { CopilotChat, CopilotKit } from '@copilotkit/angular';\n\nconst BUILT_IN_AGENT_RUNTIME_URL = 'http://localhost:8200/api/copilotkit-builtin';\n\nexport interface AgentOption {\n  /** Agent key registered in `server.ts`. */\n  id: string;\n  /** Doc section the key's snippet comes from. */\n  section: string;\n  /** A prompt that exercises the snippet. */\n  prompt: string;\n}\n\n@Component({\n  selector: 'app-agent-picker-chat',\n  imports: [CopilotChat],\n  host: { class: 'flex h-full min-h-0 gap-4 p-4' },\n  template: `\n    <nav\n      class=\"w-72 shrink-0 overflow-y-auto rounded-lg border border-slate-200 bg-white p-3\"\n      aria-label=\"Agent configurations\"\n    >\n      <ul class=\"space-y-1\">\n        @for (option of agents(); track option.id) {\n          <li>\n            <button\n              type=\"button\"\n              class=\"w-full rounded-md px-3 py-2 text-left text-sm\"\n              [class]=\"\n                option.id === selected().id\n                  ? 'bg-slate-900 text-white'\n                  : 'text-slate-700 hover:bg-slate-100'\n              \"\n              [attr.aria-pressed]=\"option.id === selected().id\"\n              (click)=\"selected.set(option)\"\n            >\n              <span class=\"block font-medium\">{{ option.section }}</span>\n              <code class=\"block text-xs opacity-80\">{{ option.id }}</code>\n            </button>\n          </li>\n        }\n      </ul>\n    </nav>\n\n    <section class=\"flex min-w-0 flex-1 flex-col gap-2\">\n      <p class=\"text-sm text-slate-700\">\n        Agent <code>{{ selected().id }}</code> — try:\n        <em>{{ selected().prompt }}</em>\n      </p>\n      <div class=\"min-h-0 flex-1 rounded-lg border border-slate-200 bg-white\">\n        @for (option of [selected()]; track option.id) {\n          <copilot-chat [agentId]=\"option.id\" />\n        }\n      </div>\n    </section>\n  `,\n})\nexport class AgentPickerChatComponent {\n  readonly agents = input.required<AgentOption[]>();\n\n  protected readonly selected = linkedSignal(() => this.agents()[0]);\n\n  constructor() {\n    const copilotKit = inject(CopilotKit);\n    const previousRuntimeUrl = copilotKit.runtimeUrl();\n    copilotKit.updateRuntime({ runtimeUrl: BUILT_IN_AGENT_RUNTIME_URL });\n    inject(DestroyRef).onDestroy(() =>\n      copilotKit.updateRuntime({ runtimeUrl: previousRuntimeUrl }),\n    );\n  }\n}\n",
  "src/app/features/built-in-agent/doc-samples.ts": "/**\n * Doc snippets this harness does not mount, extracted verbatim from the\n * published pages. Each one either uses identifiers its page never defines or\n * needs a resource this harness does not have; the route pages say which.\n *\n * https://docs.copilotkit.ai/angular/server-tools\n * https://docs.copilotkit.ai/angular/mcp-servers\n * https://docs.copilotkit.ai/angular/model-selection\n * https://docs.copilotkit.ai/angular/advanced-configuration\n */\n\n/** server-tools — \"Multiple tools\". */\nexport const SERVER_TOOLS_MULTIPLE_TOOLS = \"const searchDocs = defineTool({\\n  name: \\\"searchDocs\\\",\\n  description: \\\"Search the documentation for relevant articles\\\",\\n  parameters: z.object({\\n    query: z.string().describe(\\\"The search query\\\"),\\n  }),\\n  execute: async ({ query }) => {\\n    const results = await search(query);\\n    return { results, count: results.length };\\n  },\\n});\\n\\nconst createTicket = defineTool({\\n  name: \\\"createTicket\\\",\\n  description: \\\"Create a support ticket\\\",\\n  parameters: z.object({\\n    title: z.string().describe(\\\"Ticket title\\\"),\\n    priority: z.enum([\\\"low\\\", \\\"medium\\\", \\\"high\\\"]).describe(\\\"Ticket priority\\\"),\\n    description: z.string().describe(\\\"Detailed description of the issue\\\"),\\n  }),\\n  execute: async ({ title, priority, description }) => {\\n    const ticket = await db.tickets.create({ title, priority, description });\\n    return { ticketId: ticket.id, status: \\\"created\\\" };\\n  },\\n});\\n\\nconst builtInAgent = new BuiltInAgent({\\n  model: \\\"openai:gpt-5.4-mini\\\",\\n  tools: [searchDocs, createTicket], // [!code highlight]\\n  maxSteps: 2                        \\n});\";\n\n/** server-tools — \"Complex Zod schemas\". */\nexport const SERVER_TOOLS_COMPLEX_ZOD = \"const bookFlight = defineTool({\\n  name: \\\"bookFlight\\\",\\n  description: \\\"Search for and book flights\\\",\\n  parameters: z.object({\\n    trip: z.object({\\n      origin: z.string().describe(\\\"Origin airport code (e.g., SFO)\\\"),\\n      destination: z.string().describe(\\\"Destination airport code (e.g., JFK)\\\"),\\n      date: z.string().describe(\\\"Departure date in YYYY-MM-DD format\\\"),\\n    }),\\n    passengers: z.array(\\n      z.object({\\n        name: z.string(),\\n        seatPreference: z.enum([\\\"window\\\", \\\"middle\\\", \\\"aisle\\\"]).optional(),\\n      })\\n    ).describe(\\\"List of passengers\\\"),\\n    class: z.enum([\\\"economy\\\", \\\"business\\\", \\\"first\\\"]).default(\\\"economy\\\"),\\n  }),\\n  execute: async ({ trip, passengers, class: seatClass }) => {\\n    const flights = await searchFlights(trip, seatClass);\\n    return { flights, passengerCount: passengers.length };\\n  },\\n});\";\n\n/** server-tools — \"Error handling\". */\nexport const SERVER_TOOLS_ERROR_HANDLING = \"const getUser = defineTool({\\n  name: \\\"getUser\\\",\\n  description: \\\"Look up a user by email\\\",\\n  parameters: z.object({\\n    email: z.string().email().describe(\\\"The user's email address\\\"),\\n  }),\\n  execute: async ({ email }) => {\\n    const user = await db.users.findByEmail(email);\\n    if (!user) {\\n      throw new Error(`No user found with email: ${email}`); // [!code highlight]\\n    }\\n    return { id: user.id, name: user.name, role: user.role };\\n  },\\n});\";\n\n/** server-tools — \"Multi-step tool calling\". */\nexport const SERVER_TOOLS_MULTI_STEP = \"const builtInAgent = new BuiltInAgent({\\n  model: \\\"openai:gpt-5.4-mini\\\",\\n  maxSteps: 5, // [!code highlight]\\n  tools: [searchDocs, createTicket, getUser],\\n});\";\n\n/** mcp-servers — \"Tool caching\". */\nexport const MCP_TOOL_CACHING = \"const client = await createMCPClient({ transport });\\n\\nlet cachedTools: ToolSet | null = null;\\nconst warmupPromise = client.tools().then(tools => { cachedTools = tools; });\\n\\nconst provider = {\\n  async tools() {\\n    if (cachedTools) return cachedTools;\\n    await warmupPromise;\\n    return cachedTools!;\\n  },\\n};\\n\\nconst builtInAgent = new BuiltInAgent({\\n  model: \\\"openai:gpt-5.4-mini\\\",\\n  mcpClients: [provider], // [!code highlight]\\n});\";\n\n/** mcp-servers — \"Dynamic authentication\". */\nexport const MCP_DYNAMIC_AUTH = \"const provider = {\\n  async tools() {\\n    if (isTokenExpired()) {\\n      await currentClient.close();\\n      currentClient = await createMCPClient({\\n        transport: makeTransport(getFreshToken()),\\n      });\\n    }\\n    return currentClient.tools();\\n  },\\n};\\n\\nconst builtInAgent = new BuiltInAgent({\\n  model: \\\"openai:gpt-5.4-mini\\\",\\n  mcpClients: [provider],\\n});\";\n\n/** mcp-servers — \"Combining with mcpServers\". */\nexport const MCP_COMBINING_WITH_MCP_SERVERS = \"const builtInAgent = new BuiltInAgent({\\n  model: \\\"openai:gpt-5.4-mini\\\",\\n  mcpClients: [persistentClient],  // User-managed, persistent\\n  mcpServers: [                     // Agent-managed, per-request\\n    { type: \\\"sse\\\", url: \\\"https://other-mcp.example.com/sse\\\" },\\n  ],\\n});\";\n\n/** model-selection — \"MiniMax\". */\nexport const MODEL_MINIMAX = \"const agent = new BuiltInAgent({\\n  model: \\\"minimax:MiniMax-M3\\\",\\n});\";\n\n/** model-selection — \"Environment Variables\". */\nexport const MODEL_ENVIRONMENT_VARIABLES = \"# OpenAI\\nOPENAI_API_KEY=sk-...\\n\\n# Anthropic\\nANTHROPIC_API_KEY=sk-ant-...\\n\\n# Google\\nGOOGLE_API_KEY=...\\n\\n# MiniMax\\nMINIMAX_API_KEY=...\\n\\n# Optional: use the China endpoint\\nMINIMAX_BASE_URL=https://api.minimaxi.com/v1\";\n\n/** model-selection — \"Custom Models (AI SDK) — install\". */\nexport const MODEL_INSTALL_AI_V6 = \"npm install @ai-sdk/openai@ai-v6\";\n\n/** model-selection — \"Custom Models (AI SDK)\". */\nexport const MODEL_CUSTOM_PROVIDER = \"import { BuiltInAgent } from \\\"@copilotkit/runtime/v2\\\";\\nimport { createOpenAI } from \\\"@ai-sdk/openai\\\"; // [!code highlight]\\n\\nconst customProvider = createOpenAI({\\n  // [!code highlight]\\n  apiKey: process.env.MY_API_KEY, // [!code highlight]\\n  baseURL: \\\"https://my-proxy.example.com/v1\\\", // [!code highlight]\\n}); // [!code highlight]\\n\\nconst agent = new BuiltInAgent({\\n  model: customProvider(\\\"my-fine-tuned-model\\\"), // [!code highlight]\\n});\";\n\n/** model-selection — \"Custom Models (AI SDK) — Azure\". */\nexport const MODEL_AZURE = \"import { createAzure } from \\\"@ai-sdk/azure\\\";\\n\\nconst azure = createAzure({\\n  resourceName: \\\"my-resource\\\",\\n  apiKey: process.env.AZURE_API_KEY,\\n});\\n\\nconst agent = new BuiltInAgent({\\n  model: azure(\\\"my-deployment\\\"),\\n});\";\n\n/** model-selection — \"OpenRouter, proxies, and bring-your-own LLM\". */\nexport const MODEL_OPENROUTER = \"import { BuiltInAgent } from \\\"@copilotkit/runtime/v2\\\";\\nimport { createOpenAI } from \\\"@ai-sdk/openai\\\"; // [!code highlight]\\n\\n// OpenRouter: one key, hundreds of models behind an OpenAI-compatible API\\nconst openrouter = createOpenAI({\\n  // [!code highlight]\\n  apiKey: process.env.OPENROUTER_API_KEY, // [!code highlight]\\n  baseURL: \\\"https://openrouter.ai/api/v1\\\", // [!code highlight]\\n}); // [!code highlight]\\n\\nconst agent = new BuiltInAgent({\\n  model: openrouter(\\\"anthropic/claude-sonnet-4-6\\\"), // [!code highlight]\\n});\";\n\n/** model-selection — \"The model is set on the agent\". */\nexport const MODEL_SET_ON_AGENT = \"new BuiltInAgent({ model: \\\"openai:gpt-5.4-mini\\\" }); // built-in string\\nnew BuiltInAgent({ model: openrouter(\\\"...\\\") }); // any LanguageModel\";\n\n/** advanced-configuration — \"Multi-step tool calling\". */\nexport const ADVANCED_MULTI_STEP = \"const agent = new BuiltInAgent({\\n  model: \\\"openai:gpt-5.4-mini\\\",\\n  maxSteps: 5, // [!code highlight]\\n  tools: [searchDocs, createTicket],\\n});\";\n",
  "src/app/features/chat-ui/chat-ui-demo.component.ts": "/**\n * Harness wrapper that mounts the guide's chat surfaces one at a time.\n *\n * The popup and the sidebar each get their own tab AND their own host\n * component. The guide declares both in a single component, but both render a\n * launcher at the same fixed coordinates, so mounting them together stacks two\n * launchers on one spot and the sidebar — rendered second — swallows every\n * click. The guide's combined component stays verbatim in\n * popup-sidebar.component.ts and is what the route page displays as source.\n *\n * Bindings on the split hosts are the guide's, unchanged.\n *\n * `.support-chat` is applied to the inline tab only. It is the scope class for\n * the guide's \"Scope CSS changes\" block, which repaints the message bubbles —\n * putting it on the shared host would tint the custom-message, popup, and\n * sidebar surfaces too, and each of those is meant to show its own default\n * styling.\n */\nimport { Component, signal } from '@angular/core';\n\nimport { CustomMessageChatComponent } from './custom-message-chat.component';\nimport { PopupOnlyComponent } from './popup-only.component';\nimport { SidebarOnlyComponent } from './sidebar-only.component';\nimport { SupportChatComponent } from './support-chat.component';\n\ntype Surface = 'inline' | 'custom-message' | 'popup' | 'sidebar';\n\n@Component({\n  selector: 'app-chat-ui-demo',\n  imports: [\n    SupportChatComponent,\n    CustomMessageChatComponent,\n    PopupOnlyComponent,\n    SidebarOnlyComponent,\n  ],\n  template: `\n    <div class=\"flex h-full flex-col gap-4 p-4\">\n      <div role=\"tablist\" aria-label=\"Chat surface\" class=\"flex flex-wrap gap-2\">\n        @for (tab of tabs; track tab.id) {\n          <button\n            type=\"button\"\n            role=\"tab\"\n            [attr.aria-selected]=\"surface() === tab.id\"\n            class=\"rounded-md border px-3 py-1.5 text-sm font-medium transition-colors\"\n            [class]=\"\n              surface() === tab.id\n                ? 'border-[var(--accent)] bg-[var(--accent)] text-white'\n                : 'border-[var(--line-strong)] bg-[var(--surface)] text-[var(--ink-soft)] hover:border-[var(--accent)] hover:text-[var(--accent-ink)]'\n            \"\n            (click)=\"surface.set(tab.id)\"\n          >\n            {{ tab.label }}\n          </button>\n        }\n      </div>\n\n      <div class=\"min-h-0 flex-1\">\n        @switch (surface()) {\n          @case ('inline') {\n            <!-- Scope class for the guide's CSS block — this tab only. -->\n            <div class=\"support-chat h-full\">\n              <app-support-chat />\n            </div>\n          }\n          @case ('custom-message') {\n            <div class=\"h-full\">\n              <app-custom-message-chat />\n            </div>\n          }\n          @case ('popup') {\n            <div class=\"space-y-3\">\n              <p class=\"text-sm text-[var(--ink-soft)]\">\n                <code>copilot-popup</code> opens from a floating launcher and\n                exposes a two-way <code>open</code> model, so the harness can\n                open it from here. It manages focus, closes on Escape, and\n                restores focus to the launcher.\n              </p>\n              <button\n                type=\"button\"\n                class=\"rounded-md border border-[var(--line-strong)] bg-[var(--surface)] px-3 py-1.5 text-sm font-medium text-[var(--ink-soft)] hover:border-[var(--accent)] hover:text-[var(--accent-ink)]\"\n                (click)=\"popupHost.popupOpen.set(!popupHost.popupOpen())\"\n              >\n                {{ popupHost.popupOpen() ? 'Close' : 'Open' }} popup\n              </button>\n              <app-popup-only #popupHost />\n            </div>\n          }\n          @case ('sidebar') {\n            <div class=\"space-y-3\">\n              <p class=\"text-sm text-[var(--ink-soft)]\">\n                <code>copilot-sidebar</code> is docked to the right at 480px.\n                Compact viewports render it as a modal even when\n                <code>mode</code> is <code>\"docked\"</code>, and only one open\n                docked sidebar can own the page margin at a time.\n              </p>\n              <button\n                type=\"button\"\n                class=\"rounded-md border border-[var(--line-strong)] bg-[var(--surface)] px-3 py-1.5 text-sm font-medium text-[var(--ink-soft)] hover:border-[var(--accent)] hover:text-[var(--accent-ink)]\"\n                (click)=\"sidebarHost.sidebarOpen.set(!sidebarHost.sidebarOpen())\"\n              >\n                {{ sidebarHost.sidebarOpen() ? 'Close' : 'Open' }} sidebar\n              </button>\n              <app-sidebar-only #sidebarHost />\n            </div>\n          }\n        }\n      </div>\n    </div>\n  `,\n})\nexport class ChatUiDemoComponent {\n  protected readonly surface = signal<Surface>('inline');\n  protected readonly tabs: ReadonlyArray<{ id: Surface; label: string }> = [\n    { id: 'inline', label: 'Inline chat' },\n    { id: 'custom-message', label: 'Custom assistant message' },\n    { id: 'popup', label: 'Popup' },\n    { id: 'sidebar', label: 'Sidebar' },\n  ];\n}\n",
  "src/app/features/chat-ui/custom-assistant-message.component.ts": "/**\n * \"Replace an assistant message\", verbatim.\n * https://docs.copilotkit.ai/angular/guides/chat-ui\n */\nimport { ChangeDetectionStrategy, Component, input } from '@angular/core';\n\ntype AssistantMessage = {\n  id: string;\n  role: 'assistant';\n  content?: string;\n};\n\n@Component({\n  selector: 'app-custom-assistant-message',\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  template: `\n    <article class=\"answer\">\n      <span class=\"answer__label\">Assistant</span>\n      <p>{{ message().content }}</p>\n    </article>\n  `,\n})\nexport class CustomAssistantMessageComponent {\n  readonly message = input.required<AssistantMessage>();\n}\n",
  "src/app/features/chat-ui/custom-message-chat.component.ts": "/**\n * The second `SupportChatComponent` from \"Replace an assistant message\",\n * verbatim except for the class name and selector — the guide gives two\n * different components the same name and selector, and both are mounted here.\n * https://docs.copilotkit.ai/angular/guides/chat-ui\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { CustomAssistantMessageComponent } from './custom-assistant-message.component';\n\n@Component({\n  selector: 'app-custom-message-chat',\n  imports: [CopilotChat],\n  template: `\n    <copilot-chat\n      [assistantMessageComponent]=\"assistantMessageComponent\"\n      assistantMessageClass=\"support-answer\"\n    />\n  `,\n})\nexport class CustomMessageChatComponent {\n  protected readonly assistantMessageComponent =\n    CustomAssistantMessageComponent;\n}\n",
  "src/app/features/chat-ui/popup-only.component.ts": "/**\n * The popup half of the guide's \"Use a popup or sidebar\" sample, on its own\n * host. Bindings are the guide's, unchanged.\n *\n * The guide declares `copilot-popup` and `copilot-sidebar` in one component.\n * Both render a launcher at the same fixed coordinates\n * (`right: max(1.5rem, …); bottom: max(1.5rem, …)`), so mounting them together\n * stacks two launchers on one spot and the sidebar — rendered second — takes\n * every click. Splitting them is what makes each surface separately testable;\n * the combined component is kept verbatim in popup-sidebar.component.ts and\n * shown as the source on the route page.\n *\n * https://docs.copilotkit.ai/angular/guides/chat-ui\n */\nimport { Component, signal } from '@angular/core';\nimport { CopilotPopup } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-popup-only',\n  imports: [CopilotPopup],\n  template: `\n    <copilot-popup\n      [(open)]=\"popupOpen\"\n      title=\"Support assistant\"\n      [clickOutsideToClose]=\"true\"\n    />\n  `,\n})\nexport class PopupOnlyComponent {\n  readonly popupOpen = signal(false);\n}\n",
  "src/app/features/chat-ui/popup-sidebar.component.ts": "/**\n * \"Use a popup or sidebar\", verbatim except for the class name and selector\n * (the guide mounts it as `AppComponent` / `app-root`).\n * https://docs.copilotkit.ai/angular/guides/chat-ui\n */\nimport { Component, signal } from '@angular/core';\nimport { CopilotPopup, CopilotSidebar } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-popup-sidebar',\n  imports: [CopilotPopup, CopilotSidebar],\n  template: `\n    <copilot-popup\n      [(open)]=\"popupOpen\"\n      title=\"Support assistant\"\n      [clickOutsideToClose]=\"true\"\n    />\n\n    <copilot-sidebar\n      [(open)]=\"sidebarOpen\"\n      mode=\"docked\"\n      position=\"right\"\n      title=\"Workspace assistant\"\n      [width]=\"480\"\n    />\n  `,\n})\nexport class PopupSidebarComponent {\n  readonly popupOpen = signal(false);\n  readonly sidebarOpen = signal(false);\n}\n",
  "src/app/features/chat-ui/sidebar-only.component.ts": "/**\n * The sidebar half of the guide's \"Use a popup or sidebar\" sample, on its own\n * host. Bindings are the guide's, unchanged.\n *\n * See popup-only.component.ts for why the guide's combined component is split\n * for the demo: both surfaces render a launcher at the same fixed coordinates.\n *\n * https://docs.copilotkit.ai/angular/guides/chat-ui\n */\nimport { Component, signal } from '@angular/core';\nimport { CopilotSidebar } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-sidebar-only',\n  imports: [CopilotSidebar],\n  template: `\n    <copilot-sidebar\n      [(open)]=\"sidebarOpen\"\n      mode=\"docked\"\n      position=\"right\"\n      title=\"Workspace assistant\"\n      [width]=\"480\"\n    />\n  `,\n})\nexport class SidebarOnlyComponent {\n  readonly sidebarOpen = signal(false);\n}\n",
  "src/app/features/chat-ui/support-chat.component.ts": "/**\n * \"Add an inline chat\", verbatim.\n * https://docs.copilotkit.ai/angular/guides/chat-ui\n *\n * `agentId=\"support\"` resolves because the runtime registers a `support` agent\n * alongside `default` (see frontend/server.ts).\n */\nimport { ChangeDetectionStrategy, Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-support-chat',\n  imports: [CopilotChat],\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  template: `\n    <section class=\"chat-shell\" aria-label=\"Support assistant\">\n      <copilot-chat agentId=\"support\" />\n    </section>\n  `,\n  styles: `\n    .chat-shell {\n      height: min(48rem, 80vh);\n      overflow: hidden;\n      border: 1px solid #dbe3eb;\n      border-radius: 1rem;\n    }\n  `,\n})\nexport class SupportChatComponent {}\n",
  "src/app/features/headless/headless-chat.component.ts": "/**\n * \"Build a headless chat\", verbatim. No CopilotKit chrome: the transcript and\n * composer are hand-written over `injectAgentStore`, and the run is driven\n * through `CopilotKitCore.runAgent`.\n * https://docs.copilotkit.ai/angular/guides/threads-memory-attachments-headless\n */\nimport { Component, inject, signal } from '@angular/core';\nimport { CopilotKit, injectAgentStore } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-headless-chat',\n  template: `\n    <div aria-live=\"polite\">\n      @for (message of store().messages(); track message.id) {\n        <article [attr.data-role]=\"message.role\">\n          {{ message.content }}\n        </article>\n      }\n      @if (store().isRunning()) {\n        <p>Agent is working…</p>\n      }\n    </div>\n\n    <textarea\n      aria-label=\"Message\"\n      [value]=\"draft()\"\n      (input)=\"updateDraft($event)\"\n    ></textarea>\n    <button\n      type=\"button\"\n      [disabled]=\"store().isRunning() || !draft().trim()\"\n      (click)=\"send()\"\n    >\n      Send\n    </button>\n  `,\n})\nexport class HeadlessChatComponent {\n  private readonly copilotKit = inject(CopilotKit);\n  readonly store = injectAgentStore('default');\n  readonly draft = signal('');\n\n  protected updateDraft(event: Event): void {\n    this.draft.set((event.target as HTMLTextAreaElement).value);\n  }\n\n  protected async send(): Promise<void> {\n    const content = this.draft().trim();\n    if (!content || this.store().isRunning()) return;\n\n    const agent = this.store().agent;\n    agent.addMessage({\n      id: crypto.randomUUID(),\n      role: 'user',\n      content,\n    });\n    this.draft.set('');\n    await this.copilotKit.core.runAgent({ agent });\n  }\n}\n",
  "src/app/features/hitl/approval-card.component.ts": "/**\n * \"Register a decision tool\" renderer, verbatim.\n * https://docs.copilotkit.ai/angular/guides/human-in-the-loop\n */\nimport { Component, input } from '@angular/core';\nimport {\n  type HumanInTheLoopToolCall,\n  type HumanInTheLoopToolRenderer,\n} from '@copilotkit/angular';\n\ntype ApprovalArgs = {\n  action: string;\n  reason: string;\n};\n\n@Component({\n  selector: 'app-approval-card',\n  template: `\n    @let call = toolCall();\n    <article>\n      <h3>Approve {{ call.args.action ?? \"this action\" }}?</h3>\n      <p>{{ call.args.reason }}</p>\n\n      @if (call.status !== \"complete\") {\n        <button type=\"button\" (click)=\"call.respond({ approved: true })\">\n          Approve\n        </button>\n        <button type=\"button\" (click)=\"call.respond({ approved: false })\">\n          Reject\n        </button>\n      }\n    </article>\n  `,\n})\nexport class ApprovalCardComponent\n  implements HumanInTheLoopToolRenderer<ApprovalArgs>\n{\n  readonly toolCall = input.required<HumanInTheLoopToolCall<ApprovalArgs>>();\n}\n",
  "src/app/features/hitl/approval-tools.service.ts": "/**\n * \"Register the tool from the component or service that owns the decision UI\",\n * verbatim. There is no handler — CopilotKit supplies one that waits for\n * `respond`, returns the decision to the agent, and continues the run.\n * https://docs.copilotkit.ai/angular/guides/human-in-the-loop\n */\nimport { Injectable } from '@angular/core';\nimport { registerHumanInTheLoop } from '@copilotkit/angular';\nimport { z } from 'zod';\n\nimport { ApprovalCardComponent } from './approval-card.component';\n\n@Injectable()\nexport class ApprovalToolsService {\n  constructor() {\n    registerHumanInTheLoop({\n      name: 'requestApproval',\n      description: 'Ask the user before a consequential action',\n      parameters: z.object({\n        action: z.string(),\n        reason: z.string(),\n      }),\n      component: ApprovalCardComponent,\n    });\n  }\n}\n",
  "src/app/features/hitl/hitl-chat.component.ts": "/**\n * Puts the guide's two human-in-the-loop paths side by side: the decision tool\n * (registered by ApprovalToolsService, rendered inside the chat's tool-call\n * flow) and the headless interrupt controller (rendered outside the chat).\n * https://docs.copilotkit.ai/angular/guides/human-in-the-loop\n *\n * Injecting ApprovalToolsService is what constructs it, and construction is\n * what performs the `registerHumanInTheLoop` call.\n */\nimport { Component, inject } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { ApprovalToolsService } from './approval-tools.service';\nimport { InterruptPanelComponent } from './interrupt-panel.component';\n\n@Component({\n  selector: 'app-hitl-chat',\n  imports: [CopilotChat, InterruptPanelComponent],\n  providers: [ApprovalToolsService],\n  template: `\n    <div style=\"display: flex; flex-direction: column; height: 100%\">\n      <app-interrupt-panel />\n      <div style=\"flex: 1; min-height: 0\">\n        <copilot-chat />\n      </div>\n    </div>\n  `,\n})\nexport class HitlChatComponent {\n  private readonly approvalTools = inject(ApprovalToolsService);\n}\n",
  "src/app/features/hitl/interrupt-panel.component.ts": "/**\n * \"Handle an interrupt\", verbatim. The controller is headless, so this panel\n * renders nothing until the backend emits an AG-UI interrupt.\n * https://docs.copilotkit.ai/angular/guides/human-in-the-loop\n */\nimport { Component } from '@angular/core';\nimport { injectInterrupt } from '@copilotkit/angular';\n\ntype ReviewRequest = {\n  title?: string;\n  choices?: Array<{ id: string; label: string }>;\n};\n\n@Component({\n  selector: 'app-interrupt-panel',\n  template: `\n    @if (controller.event(); as event) {\n      @let request = asReviewRequest(event.value);\n      <section aria-labelledby=\"review-title\">\n        <h2 id=\"review-title\">{{ request.title ?? \"Review required\" }}</h2>\n\n        @for (choice of request.choices ?? []; track choice.id) {\n          <button type=\"button\" (click)=\"resolve(choice.id)\">\n            {{ choice.label }}\n          </button>\n        }\n\n        <button type=\"button\" (click)=\"cancel()\">Cancel</button>\n      </section>\n    }\n\n    @if (controller.error()) {\n      <p role=\"alert\">The decision could not be submitted.</p>\n    }\n  `,\n})\nexport class InterruptPanelComponent {\n  protected readonly controller = injectInterrupt<ReviewRequest>({\n    agentId: 'default',\n  });\n\n  protected asReviewRequest(value: unknown): ReviewRequest {\n    return typeof value === 'object' && value !== null\n      ? (value as ReviewRequest)\n      : {};\n  }\n\n  protected resolve(choiceId: string): void {\n    this.controller.resolve({ choiceId }).catch(() => undefined);\n  }\n\n  protected cancel(): void {\n    this.controller.cancel().catch(() => undefined);\n  }\n}\n",
  "src/app/features/media/voice-chat.component.ts": "/**\n * \"Configure attachments\", verbatim: the guide's `MULTIMODAL_ATTACHMENTS`\n * config bound to the chat exactly as its `media-chat.component.html` snippet\n * shows. The microphone control needs no option — it is always present.\n * https://docs.copilotkit.ai/angular/guides/voice-multimodal\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat, type AttachmentsConfig } from '@copilotkit/angular';\n\nconst MULTIMODAL_ATTACHMENTS: AttachmentsConfig = {\n  enabled: true,\n  accept: 'image/*,application/pdf',\n  maxSize: 10 * 1024 * 1024,\n};\n\n@Component({\n  selector: 'app-voice-chat',\n  imports: [CopilotChat],\n  template: `\n    <div style=\"height: 100%\">\n      <copilot-chat [attachments]=\"multimodalAttachments\" />\n    </div>\n  `,\n})\nexport class VoiceChatComponent {\n  protected readonly multimodalAttachments = MULTIMODAL_ATTACHMENTS;\n}\n",
  "src/app/features/memory/memory-demo.component.ts": "/**\n * Harness wrapper mounting the guide's memory list beside a chat, so the\n * `isAvailable()` gate can be observed against a live runtime.\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { MemoryListComponent } from './memory-list.component';\n\n@Component({\n  selector: 'app-memory-demo',\n  imports: [CopilotChat, MemoryListComponent],\n  template: `\n    <div class=\"flex h-full gap-4 p-4\">\n      <section\n        class=\"w-80 shrink-0 overflow-y-auto rounded-lg border border-slate-200 bg-white p-4\"\n      >\n        <h2 class=\"mb-2 text-sm font-semibold text-slate-900\">\n          injectMemories\n        </h2>\n        <app-memory-list />\n      </section>\n      <div class=\"min-w-0 flex-1\">\n        <copilot-chat />\n      </div>\n    </div>\n  `,\n})\nexport class MemoryDemoComponent {}\n",
  "src/app/features/memory/memory-list.component.ts": "/**\n * \"Read and manage memory\", verbatim. The `isAvailable()` gate is the point of\n * the sample: a runtime may not provide the memory routes at all.\n * https://docs.copilotkit.ai/angular/guides/threads-memory-attachments-headless\n */\nimport { Component } from '@angular/core';\nimport { injectMemories } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-memory-list',\n  template: `\n    @if (!memory.isAvailable()) {\n      <p>Memory is not available for this runtime.</p>\n    } @else {\n      @for (item of memory.memories(); track item.id) {\n        <article>\n          <p>{{ item.content }}</p>\n          <button type=\"button\" (click)=\"remove(item.id)\">Forget</button>\n        </article>\n      }\n    }\n  `,\n})\nexport class MemoryListComponent {\n  readonly memory = injectMemories();\n\n  protected remove(id: string): void {\n    this.memory.removeMemory(id).catch(() => undefined);\n  }\n\n  protected addPreference(): void {\n    this.memory\n      .addMemory({\n        kind: 'operational',\n        content: 'Prefer concise status updates.',\n      })\n      .catch(() => undefined);\n  }\n}\n",
  "src/app/features/quickstart/quickstart-chat.ts": "/**\n * Quickstart step \"Add the chat UI\", verbatim.\n * https://docs.copilotkit.ai/angular\n *\n * Only the selector and class name differ from the doc (which mounts this as\n * the app root); the template and imports are unchanged.\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-quickstart-chat',\n  imports: [CopilotChat],\n  template: `\n    <div style=\"height: 100vh\">\n      <copilot-chat />\n    </div>\n  `,\n})\nexport class QuickstartChat {}\n",
  "src/app/features/shared-state/account-context.component.ts": "/**\n * \"Send read-only application context\", verbatim. The accessor form keeps the\n * signal reads reactive, so changing the timezone re-registers the context.\n * https://docs.copilotkit.ai/angular/guides/shared-state\n */\nimport { Component, signal } from '@angular/core';\nimport { connectAgentContext } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-account-context',\n  template: `\n    <br>\n    <button type=\"button\" (click)=\"timezone.set('Europe/London')\">\n      Use London time\n    </button>\n  `,\n})\nexport class AccountContextComponent {\n  readonly userName = signal('Ada');\n  readonly timezone = signal('America/Los_Angeles');\n\n  constructor() {\n    connectAgentContext(() => ({\n      description: 'Current account and timezone',\n      value: JSON.stringify({\n        userName: this.userName(),\n        timezone: this.timezone(),\n      }),\n    }));\n  }\n}\n",
  "src/app/features/shared-state/selection-context.component.ts": "/**\n * \"Bind context in a template\", verbatim. The directive registers on first\n * render, so it must not be rendered before the context is complete.\n * https://docs.copilotkit.ai/angular/guides/shared-state\n */\nimport { Component, computed, signal } from '@angular/core';\nimport { CopilotKitAgentContext } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-selection-context',\n  imports: [CopilotKitAgentContext],\n  template: ` <div [copilotkitAgentContext]=\"selectionContext()\"></div> `,\n})\nexport class SelectionContextComponent {\n  readonly selectedId = signal('record-42');\n  readonly selectionContext = computed(() => ({\n    description: 'The record selected in the application',\n    value: this.selectedId(),\n  }));\n}\n",
  "src/app/features/shared-state/shared-state-chat.component.ts": "/**\n * Mounts the guide's three surfaces against one chat: the read/write state\n * panel, the accessor-based context, and the directive-based context.\n * https://docs.copilotkit.ai/angular/guides/shared-state\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { AccountContextComponent } from './account-context.component';\nimport { SelectionContextComponent } from './selection-context.component';\nimport { WorkspaceComponent } from './workspace.component';\n\n@Component({\n  selector: 'app-shared-state-chat',\n  imports: [\n    CopilotChat,\n    WorkspaceComponent,\n    AccountContextComponent,\n    SelectionContextComponent,\n  ],\n  template: `\n    <div style=\"display: flex; height: 100%; gap: 1rem\">\n      <div style=\"width: 20rem; overflow-y: auto; padding: 1rem\">\n        <app-workspace />\n        <app-account-context />\n        <app-selection-context />\n      </div>\n      <div style=\"flex: 1; min-width: 0\">\n        <copilot-chat />\n      </div>\n    </div>\n  `,\n})\nexport class SharedStateChatComponent {}\n",
  "src/app/features/shared-state/workspace.component.ts": "/**\n * \"Read agent state\", verbatim. Reads through `store().state()` so Angular\n * tracks changes; writes through the plain AG-UI agent at `store().agent`.\n * https://docs.copilotkit.ai/angular/guides/shared-state\n */\nimport { Component, computed } from '@angular/core';\nimport { injectAgentStore } from '@copilotkit/angular';\n\ntype WorkspaceState = {\n  notes: string[];\n  priority: 'low' | 'normal' | 'high';\n};\n\nconst EMPTY_STATE: WorkspaceState = {\n  notes: [],\n  priority: 'normal',\n};\n\n@Component({\n  selector: 'app-workspace',\n  template: `\n    <p>Priority: {{ state().priority }}</p>\n    <ul>\n      @for (note of state().notes; track note) {\n        <li>{{ note }}</li>\n      }\n    </ul>\n    <button type=\"button\" (click)=\"setPriority('high')\">\n      Mark high priority\n    </button>\n    <br>\n     <button type=\"button\" (click)=\"setPriority('low')\">\n      Mark low priority\n    </button>\n  `,\n})\nexport class WorkspaceComponent {\n  readonly store = injectAgentStore('default');\n  readonly state = computed(\n    () => (this.store().state() as WorkspaceState | undefined) ?? EMPTY_STATE,\n  );\n\n  protected setPriority(priority: WorkspaceState['priority']): void {\n    const agent = this.store().agent;\n    const current = (agent.state as WorkspaceState | undefined) ?? EMPTY_STATE;\n    agent.setState({ ...current, priority });\n  }\n}\n",
  "src/app/features/threads/conversations.component.ts": "/**\n * The drawer-plus-chat sample, verbatim. Both sit under one\n * `provideCopilotChatConfiguration`, which is what makes selection and\n * new-thread actions in the drawer update the chat.\n * https://docs.copilotkit.ai/angular/guides/threads-memory-attachments-headless\n */\nimport { Component } from '@angular/core';\nimport {\n  CopilotChat,\n  CopilotThreadsDrawer,\n  provideCopilotChatConfiguration,\n} from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-conversations',\n  imports: [CopilotChat, CopilotThreadsDrawer],\n  providers: [provideCopilotChatConfiguration({ agentId: 'support' })],\n  // Layout lives on the host and in scoped styles, never in the template: the\n  // two element tags below are the guide's sample and stay byte-identical to it.\n  // Without this the host is `display: inline`, so the drawer and chat ignore\n  // the flex row they sit in and the chat shrink-wraps to a narrow column.\n  host: { class: 'flex min-h-0 flex-1 gap-4' },\n  styles: `\n    copilot-threads-drawer {\n      display: block;\n      flex: 0 0 16rem;\n      min-height: 0;\n      overflow-y: auto;\n    }\n    copilot-chat {\n      display: block;\n      flex: 1 1 auto;\n      min-width: 0;\n      min-height: 0;\n    }\n  `,\n  template: `\n    <copilot-threads-drawer agentId=\"support\" [limit]=\"20\" />\n    <copilot-chat />\n  `,\n})\nexport class ConversationsComponent {}\n",
  "src/app/features/threads/thread-list.component.ts": "/**\n * \"For a custom thread list, use injectThreads\", verbatim.\n * https://docs.copilotkit.ai/angular/guides/threads-memory-attachments-headless\n */\nimport { Component } from '@angular/core';\nimport { injectThreads } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-thread-list',\n  template: `\n    <button type=\"button\" (click)=\"threads.startNewThread()\">\n      New conversation\n    </button>\n\n    @if (threads.isLoading()) {\n      <p>Loading conversations…</p>\n    } @else {\n      @for (thread of threads.threads(); track thread.id) {\n        <button type=\"button\" (click)=\"select(thread.id)\">\n          {{ thread.name ?? \"Untitled conversation\" }}\n        </button>\n      }\n    }\n\n    @if (threads.listError()) {\n      <button type=\"button\" (click)=\"threads.refetchThreads()\">Retry</button>\n    }\n  `,\n})\nexport class ThreadListComponent {\n  readonly threads = injectThreads({\n    agentId: 'support',\n    limit: 20,\n  });\n\n  protected select(threadId: string): void {\n    // Store this id and bind it to CopilotChat's threadId input.\n    console.log(threadId);\n  }\n}\n",
  "src/app/features/threads/threads-demo.component.ts": "/**\n * Harness wrapper mounting both thread surfaces from the guide: the hand-built\n * list on `injectThreads`, and the drop-in drawer beside a chat.\n */\nimport { Component } from '@angular/core';\n\nimport { ConversationsComponent } from './conversations.component';\nimport { ThreadListComponent } from './thread-list.component';\n\n@Component({\n  selector: 'app-threads-demo',\n  imports: [ThreadListComponent, ConversationsComponent],\n  template: `\n    <div class=\"flex h-full flex-col gap-4 p-4\">\n      <section class=\"rounded-lg border border-slate-200 bg-white p-4\">\n        <h2 class=\"mb-2 text-sm font-semibold text-slate-900\">\n          Headless list — injectThreads\n        </h2>\n        <app-thread-list />\n      </section>\n\n      <section\n        class=\"flex min-h-0 flex-1 flex-col rounded-lg border border-slate-200 bg-white p-4\"\n      >\n        <h2 class=\"mb-2 text-sm font-semibold text-slate-900\">\n          CopilotThreadsDrawer + chat\n        </h2>\n        <div class=\"flex min-h-0 flex-1 gap-4\">\n          <app-conversations />\n        </div>\n      </section>\n    </div>\n  `,\n})\nexport class ThreadsDemoComponent {}\n",
  "src/app/features/tools/incident-card.component.ts": "/**\n * \"Let the agent display one of your components\", verbatim.\n * https://docs.copilotkit.ai/angular/guides/frontend-tools-generative-ui\n *\n * Two deviations from the published snippet, both mechanical:\n * `standalone: true` is dropped — it is the default on Angular v20+ and\n * frontend/AGENTS.md forbids setting it — and the two imports are narrowed to\n * `type` imports, matching weather-card.component.ts.\n *\n * Unlike WeatherCardComponent this renderer never reads `call.result`: a\n * display-only component has no application code behind it, so the tool\n * completes with an empty result and the args are the whole payload.\n */\nimport { Component, input } from '@angular/core';\nimport { type AngularToolCall, type ToolRenderer } from '@copilotkit/angular';\n\ntype IncidentArgs = { id: string; severity: string };\n\n@Component({\n  selector: 'app-incident-card',\n  template: `\n    @let call = toolCall();\n    @if (call.status === \"in-progress\") {\n      <p>Loading incident…</p>\n    } @else {\n      <article>\n        <strong>{{ call.args.id }}</strong>\n        <span>{{ call.args.severity }}</span>\n      </article>\n    }\n  `,\n})\nexport class IncidentCardComponent implements ToolRenderer<IncidentArgs> {\n  readonly toolCall = input.required<AngularToolCall<IncidentArgs>>();\n}\n",
  "src/app/features/tools/tool-feature-model.ts": "/**\n * The guide's `change_background` frontend tool.\n * https://docs.copilotkit.ai/angular/guides/frontend-tools-generative-ui\n *\n * `createBackgroundTool` is the guide's function, unchanged. Everything above\n * it is not in the guide: the snippet is quoted from the live Showcase without\n * its `BackgroundToolArgs` type, its `resolveGradient` helper, or its imports,\n * so those are defined here to make it runnable.\n */\nimport { type WritableSignal } from '@angular/core';\nimport { type FrontendToolConfig } from '@copilotkit/angular';\nimport { z } from 'zod';\n\n/** Arguments the agent may send to `change_background`. */\nexport type BackgroundToolArgs = {\n  background?: string;\n  color?: string;\n};\n\n/** Named presets so the agent can ask for a look without writing CSS. */\nconst GRADIENT_PRESETS: Record<string, string> = {\n  blue: 'linear-gradient(180deg, #0c4a6e 0%, #38bdf8 100%)',\n  violet: 'linear-gradient(180deg, #4c1d95 0%, #c084fc 100%)',\n  sunset: 'linear-gradient(180deg, #f97316 0%, #db2777 55%, #7c3aed 100%)',\n  forest: 'linear-gradient(180deg, #14532d 0%, #4ade80 100%)',\n  slate: 'linear-gradient(180deg, #0f172a 0%, #475569 100%)',\n};\n\nexport const DEFAULT_BACKGROUND = GRADIENT_PRESETS['slate'];\n\n/**\n * Accept a preset name, a bare CSS color, or a full gradient and always return\n * something safe to drop into a `background` style binding.\n */\nexport function resolveGradient(value: string | undefined): string {\n  const raw = value?.trim();\n  if (!raw) {\n    return DEFAULT_BACKGROUND;\n  }\n\n  const preset = GRADIENT_PRESETS[raw.toLowerCase()];\n  if (preset) {\n    return preset;\n  }\n\n  return raw.includes('gradient(')\n    ? raw\n    : `linear-gradient(180deg, ${raw} 0%, ${raw} 100%)`;\n}\n\n/** Create the frontend tool that applies a requested CSS gradient. */\nexport function createBackgroundTool(\n  background: WritableSignal<string>,\n): FrontendToolConfig<BackgroundToolArgs> {\n  return {\n    name: 'change_background',\n    description: 'Change the application background to a CSS gradient.',\n    parameters: z.object({\n      background: z.string().optional(),\n      color: z.string().optional(),\n    }),\n    handler: async (args) => {\n      const next = resolveGradient(args.background ?? args.color);\n      background.set(next);\n      return { background: next };\n    },\n  };\n}\n",
  "src/app/features/tools/tools-chat.component.ts": "/**\n * Mounts all three of the guide's frontend-tool paths against one chat.\n *\n * `registerRenderToolCall` — the tool runs on the server (the Agent Framework\n * agent's weather tool) and the browser only renders its call, through\n * WeatherCardComponent.\n *\n * `registerComponent` — display only. `show_incident` has neither a handler\n * nor a tool on the agent: the frontend declares it, CopilotKit forwards it\n * over AG-UI, and the agent calls it purely to put IncidentCardComponent on\n * screen. Core inserts an empty tool result, so the turn completes without an\n * invented result being written into the thread.\n *\n * `registerFrontendTool` — the tool runs in the browser. `change_background`\n * has a handler and no component, so it renders nothing in chat; its result is\n * the page itself changing. The registration is removed when this injector is\n * destroyed.\n *\n * The guide's other `registerFrontendTool` sample is a second `getWeather`\n * that runs in the browser. It is not mounted: it would collide with the\n * server-side tool of the same name, and it calls an `/api/weather` endpoint\n * this repo does not serve.\n *\n * https://docs.copilotkit.ai/angular/guides/frontend-tools-generative-ui\n */\nimport { Component, signal } from '@angular/core';\nimport {\n  CopilotSidebar,\n  registerComponent,\n  registerFrontendTool,\n  registerRenderToolCall,\n} from '@copilotkit/angular';\nimport { z } from 'zod';\n\nimport {\n  DEFAULT_BACKGROUND,\n  createBackgroundTool,\n} from './tool-feature-model';\nimport { IncidentCardComponent } from './incident-card.component';\nimport { WeatherCardComponent } from './weather-card.component';\n\n@Component({\n  selector: 'app-tools-chat',\n  imports: [CopilotSidebar],\n  template: `\n    <div\n      style=\"height: 100%; display: flex; flex-direction: column; gap: 0.75rem; padding: 0.75rem; transition: background 400ms ease\"\n      [style.background]=\"background()\"\n    >\n        <copilot-sidebar />\n\n    </div>\n  `,\n})\nexport class ToolsChatComponent {\n  /** Written by the agent through the change_background handler. */\n  protected readonly background = signal(DEFAULT_BACKGROUND);\n\n  constructor() {\n    registerRenderToolCall({\n      name: 'getWeather',\n      args: z.object({ city: z.string() }),\n      component: WeatherCardComponent,\n    });\n\n    registerComponent({\n      name: 'show_incident',\n      description: 'Show one incident from the incident table.',\n      parameters: z.object({\n        id: z.string().describe('The incident id, such as INC-4711'),\n        severity: z.string().describe('One of sev1, sev2, sev3'),\n      }),\n      component: IncidentCardComponent,\n    });\n\n    registerFrontendTool(createBackgroundTool(this.background));\n  }\n}\n",
  "src/app/features/tools/weather-card.component.ts": "/**\n * \"Render a tool result\", verbatim.\n * https://docs.copilotkit.ai/angular/guides/frontend-tools-generative-ui\n */\nimport { Component, input } from '@angular/core';\nimport { type AngularToolCall, type ToolRenderer } from '@copilotkit/angular';\n\ntype WeatherArgs = { city: string };\n\n@Component({\n  selector: 'app-weather-card',\n  template: `\n    @let call = toolCall();\n    @if (call.status === \"complete\") {\n      <article>\n        <strong>{{ call.args.city }}</strong>\n        <p>{{ call.result }}</p>\n      </article>\n    } @else {\n      <p>Loading weather for {{ call.args.city ?? \"…\" }}</p>\n    }\n    <p>Tool Call done </p>\n  `,\n})\nexport class WeatherCardComponent implements ToolRenderer<WeatherArgs> {\n  readonly toolCall = input.required<AngularToolCall<WeatherArgs>>();\n}\n",
};

export function readSource(path: string): string {
  return SOURCES[path] ?? `// Source not generated for ${path}. Run: npm run gen:sources`;
}
